SELECT review_id, business_id, user_id, stars, date, text
FROM review
WHERE review_id IN ('r1','r2','r3');

MATCH (u:User {user_id:$user_id})-[:FRIEND]->(f:User)-[r:REVIEWED]->(b:Business {business_id:$business_id})
WHERE r.stars >= 4
RETURN count(DISTINCT f) AS friends_like_cnt, collect(DISTINCT coalesce(f.name,f.user_id))[0..5] AS sample_friends;

